const key='pino-workforce-v2-config';let data=JSON.parse(localStorage.getItem(key)||'null')||{weeks:[{from:'2026-10-12',to:'2026-10-18',registration:false,assignment:true,final:false}],templates:[]};let editing=-1;function persist(){localStorage.setItem(key,JSON.stringify(data))}function pill(v,on,off){return '<span class="pill '+(v?'':'off')+'">'+(v?on:off)+'</span>'}function render(){let q=document.getElementById('search').value.toLowerCase(),f=document.getElementById('filter').value;let arr=data.weeks.map((w,i)=>({w,i})).filter(({w})=>((w.name||'')+' '+w.from+' '+w.to).toLowerCase().includes(q)&&(f==='all'||(f==='open'&&w.assignment&&!w.final)||(f==='closed'&&w.final)));document.getElementById('rows').innerHTML=arr.map(({w,i})=>'<tr><td><strong>'+(w.name||'TW-'+w.from)+'</strong><br><small>TW-'+w.from+'</small></td><td>'+w.from+'</td><td>'+w.to+'</td><td>'+pill(w.registration,'Mở','Đóng')+'</td><td>'+pill(w.assignment,'Mở','Đóng')+'</td><td>'+pill(w.final,'Đã chốt','Chưa chốt')+'</td><td>'+(w.until||'—')+'</td><td><button class="linkbtn" onclick="manage('+i+')">Quản lý</button> <a href="/?termweek='+encodeURIComponent(w.from)+'">Xếp ca →</a></td></tr>').join('')||'<tr><td colspan="8" class="empty">Không có TermWeek phù hợp.</td></tr>'}function openCreate(){editing=-1;document.getElementById('weekName').value='';document.getElementById('modalTitle').textContent='Tạo TermWeek';document.getElementById('createFields').style.display='block';document.getElementById('manageFields').style.display='none';document.getElementById('overlay').style.display='flex'}function manage(i){editing=i;let w=data.weeks[i];document.getElementById('weekName').value=w.name||'';document.getElementById('modalTitle').textContent='Quản lý · '+w.from;document.getElementById('createFields').style.display='none';document.getElementById('manageFields').style.display='block';for(let k of ['registration','assignment','final'])document.getElementById(k).checked=!!w[k];document.getElementById('until').value=w.until||'';document.getElementById('reason').value='';document.getElementById('overlay').style.display='flex'}function closeModal(){document.getElementById('overlay').style.display='none'}function save(){let weekName=document.getElementById('weekName').value.trim();if(!weekName)return alert('Vui lòng nhập Week name');if(editing<0){let from=document.getElementById('from').value,to=document.getElementById('to').value;if(!from||!to||to<from)return alert('Ngày không hợp lệ');if(data.weeks.some(w=>w.from===from))return alert('TermWeek đã tồn tại');data.weeks.push({name:weekName,from,to,registration:true,assignment:true,final:false});}else{let w=data.weeks[editing],newValues={};w.name=weekName;for(let k of ['registration','assignment','final'])newValues[k]=document.getElementById(k).checked;let changed=Object.keys(newValues).some(k=>w[k]!==newValues[k]);let reason=document.getElementById('reason').value.trim();if(changed&&!reason)return alert('Nhập lý do thay đổi trạng thái');if(newValues.final&&newValues.assignment)return alert('Tuần đã chốt không thể đồng thời mở xếp ca');Object.assign(w,newValues,{until:document.getElementById('until').value,reason:reason||w.reason});}persist();closeModal();render()}render();